   <section class="card"><div class="ch2"><h3>Recent activity</h3><button class="link" data-view="audit">View all</button></div>${ACT.length?ACT.map(a=>{const m=ACTL[a.action]||['list',a.action.toLowerCase().replace(/_/g,' ')];return`<div class="act"><span class="kico sm" style="--c:#6d7cff">${ic(m[0])}</span><div class="f1"><b>${esc((a.actor||'system').split('@')[0])}</b> ${m[1]}<small>${esc(a.details||'')}</small></div><time>${ago(a.created_at)}</time></div>`}).join(''):`<div class="empty">${ic('list')}<b>No activity yet</b><small>Uploads, syncs and reviews will appear here.</small></div>`}</section>
