const VT={dash:['Overview','Compliance at a glance'],students:['Students','Roster, seat map and status'],requirements:['Certificate types','Types students can upload and their Drive folders'],access:['Student access','Sign-in codes for students'],review:['Needs review','Duplicates and mismatches'],alerts:['Alerts','Broadcast to students'],export:['Export','Reports and downloads'],audit:['Audit log','Every action, recorded']};
let CI=0,CL=[];
const cmdItems=q=>{q=q.toLowerCase();return[...Object.entries(VT).filter(([k,v])=>v[0].toLowerCase().includes(q)).map(([k,v])=>({t:v[0],s:'Go to',a:()=>setView(k)})),...(q?ST.filter(x=>x.n.toLowerCase().includes(q)||x.r.toLowerCase().includes(q)).slice(0,8).map(x=>({t:x.n,s:x.r,a:()=>openStudent(x.r)})):[])]};
