const closeCmd=()=>{$('#cmdk').innerHTML=''};
function openCmd(){if(!ME||ME.role!=='faculty')return;$('#cmdk').innerHTML='<div class="cmd-back"><div class="cmd"><input id="cmdq" placeholder="Search students or jump to a page…" autocomplete="off" aria-label="Command palette"><div id="cmdl"></div></div></div>';CL=cmdItems('');CI=0;cmdPaint();$('#cmdq').focus()}
document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCmd();return}
  if(!$('#cmdq'))return;
  if(e.key==='Escape')closeCmd();else if(e.key==='ArrowDown'){e.preventDefault();CI=Math.min(CI+1,CL.length-1);cmdPaint()}else if(e.key==='ArrowUp'){e.preventDefault();CI=Math.max(CI-1,0);cmdPaint()}else if(e.key==='Enter'&&CL[CI]){const a=CL[CI].a;closeCmd();a()}});
