  if(t.dataset.f){U.f=t.dataset.f;chips();body()}
  if(t.dataset.m){U.m=t.dataset.m;chips();body()}
  if(t.dataset.mode){U.mode=t.dataset.mode;body()}
  if(t.dataset.vw){U.vw=t.dataset.vw;body()}
  if(t.dataset.view)setView(t.dataset.view);
