const ok=async p=>{const {data,error}=await p;if(error)throw error;return data};
const fnErr=async e=>{try{const x=await e.context.json();return new Error(x.error||e.message)}catch{return e}};
const call=async(n,body)=>{const {data,error}=await sb.functions.invoke(n,{body});if(error)throw await fnErr(error);return data};
const fetchAll=async q=>{let out=[];for(let i=0;;i+=1000){const d=await ok(q(i,i+999));out=out.concat(d);if(d.length<1000)break}return out};
const closeM=c=>{$('#modal').innerHTML='';if(c&&ASKR){ASKR();ASKR=null}};
const modal=h=>{$('#modal').innerHTML=`<div class="mback"><div class="mbox">${h}</div></div>`};
const copyText=async t=>{try{await navigator.clipboard.writeText(t);return true}catch(e){try{const x=document.createElement('textarea');x.value=t;x.style.cssText='position:fixed;opacity:0';document.body.append(x);x.select();const r=document.execCommand('copy');x.remove();return !!r}catch(_){return false}}};
document.addEventListener('mousedown',e=>{if(e.target.classList&&e.target.classList.contains('mback'))closeM(1)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeM(1)});
function ask(title,fields,okTxt='Save'){return new Promise(res=>{modal(`<h3>${title}</h3><form id="af" class="g">${fields.map(f=>`<label class="lb">${f.l}${f.ta?`<textarea class="in" name="${f.n}" rows="7">${esc(f.v||'')}</textarea>`:f.opts?`<select class="in" name="${f.n}">${f.opts.map(([v,l])=>`<option value="${v}"${v===f.v?' selected':''}>${l}</option>`).join('')}</select>`:`<input class="in" type="${f.t||'text'}" name="${f.n}" value="${esc(f.v==null?'':f.v)}">`}</label>`).join('')}<div class="row" style="justify-content:flex-end"><button type="button" class="btn o" data-act="mclose">Cancel</button><button class="btn b">${okTxt}</button></div></form>`);ASKR=()=>res(null);$('#af').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));ASKR=null;closeM();res(o)}})}
function gate(html){$('#gate').innerHTML=html?`<div class="gate"><div class="card"><div class="logo">🎓</div><h2 style="margin:0">Certifyx</h2><p style="margin:-6px 0 2px">Upload your certificates in under a minute</p>${html}</div></div>`:''}
/* duplicates: identical rule to the server (same student + same file name; different names are never duplicates) */
const dk=c=>c.roll_no+'|'+(c.file_name==='(sheet only)'?'s|'+(c.category||'').toLowerCase()+'|'+(c.title||'').toLowerCase():String(c.file_name).toLowerCase());
const dupExtras=cs=>{const g={},sc=c=>c.in_drive&&c.in_sheet?2:c.in_drive||c.in_sheet?1:0;cs.forEach(c=>(g[dk(c)]=g[dk(c)]||[]).push(c));return Object.values(g).filter(l=>l.length>1).flatMap(l=>l.sort((a,b)=>sc(b)-sc(a)||String(a.created_at).localeCompare(String(b.created_at))).slice(1))};
const grpF=g=>s=>{const o=done(s)?'C':s.d>0||s.s>0?'P':'N';return g==='NOT_STARTED'?o==='N':g==='PENDING'?o==='P':g==='REJECTED'?s.ap==='REJECTED':g==='APPROVED'?s.ap==='APPROVED':g==='DEFAULTERS'?(o!=='C'||s.ap==='REJECTED'):true};

const TR=[];
const hint=e=>{const m=String(e&&e.message||e);
  return /access_denied|not.*test.*user|verification process|blocked/i.test(m)?'Google blocked this account. If the OAuth consent screen is in Testing mode, add the account under "Test users" (or publish the app: In production). For a school Workspace choose "Internal" and sign in with a school account.'
  :/Database error saving new user/i.test(m)?'Supabase could not create the profile row. Re-run supabase/schema.sql (handle_new_user trigger), then look at Supabase → Logs → Auth.'
  :/Unable to exchange external code|invalid_client|client_secret|unauthorized_client/i.test(m)?'The Google client ID / secret in Supabase → Authentication → Providers → Google is wrong. Re-paste both from Google Cloud Console (Credentials → your OAuth client).'
  :/Invalid API key|apikey|No API key/i.test(m)?'The anon key in config.js is wrong. Copy the "anon public" key from Supabase → Project Settings → API.'
  :/relation .* does not exist|schema cache|Could not find the table|Could not find the function/i.test(m)?'Database tables/functions are missing — run supabase/schema.sql (then seed.sql) in the Supabase SQL Editor.'
  :/Failed to fetch|NetworkError|Load failed/i.test(m)?'Cannot reach Supabase. Check the project URL in config.js (it looks like https://abcdxyz.supabase.co) and your connection.'
  :/provider is not enabled|Unsupported provider/i.test(m)?'Enable Google in Supabase → Authentication → Providers → Google.'
  :/redirect|mismatch|requested path is invalid|uri/i.test(m)?'Add this site\'s address to Supabase → Authentication → URL Configuration (Site URL + Redirect URLs) and to the Google OAuth client\'s authorised redirect URIs.'
  :/JWT|expired|invalid_grant/i.test(m)?'Your session expired — sign out and sign in again.':''};
const fail=(title,e)=>gate(`<p><b>${title}</b></p><p class="mono" style="word-break:break-word;font-size:13px;color:#fb7195">${esc(e&&e.message||e)}</p>${hint(e)?`<p>${esc(hint(e))}</p>`:''}<p style="font-size:13px"><a href="check.html">Run the full setup check</a></p>${TR.length?`<details style="text-align:left;font-size:12px"><summary>Details</summary><pre class="mono" style="white-space:pre-wrap">${esc(TR.join('\n'))}</pre></details>`:''}<div class="row" style="justify-content:center"><button class="big" data-act="google">Try again</button><button class="ghost" data-act="signout">Sign out</button></div>`);
async function boot(){try{await boot2()}catch(e){fail('Startup problem',e)}}
addEventListener('unhandledrejection',e=>toast(String(e.reason&&e.reason.message||e.reason)));
const STK='cx-student-token';let FNB='',POLL=null;
function loginGate(note){gate(`${note?`<p style="color:var(--am);font-size:13px">${esc(note)}</p>`:''}<form id="slf" class="g" style="width:100%;text-align:left"><label class="lb">Roll number<input class="in" name="roll" autocomplete="username" autocapitalize="characters" spellcheck="false" required></label><label class="lb">Access code<input class="in" name="code" autocomplete="current-password" spellcheck="false" placeholder="XXXXX-XXXXX" required></label><button class="big">Sign in</button><p id="slerr" style="color:var(--rd);min-height:20px;font-size:13px;margin:0"></p></form><div class="or"><span>Faculty / admin</span></div><button class="ghost" data-act="google">Continue with Google</button><p style="font-size:12px;margin:0"><a href="check.html">Setup check</a></p>`)}
async function sapi(action,payload={},o={}){
  const tok=o.noToken?'':localStorage.getItem(STK)||'',H={'x-student-token':tok,apikey:(window.CX||{}).anon||''};let body;
  if(payload instanceof FormData){payload.append('action',action);body=payload}else{H['Content-Type']='application/json';body=JSON.stringify({action,...payload})}
  const r=await fetch(FNB+'/student-api',{method:'POST',headers:H,body}),j=await r.json().catch(()=>({error:'Unexpected answer from the server'}));
  if(r.status===401&&!o.noToken){studentOut(true);throw new Error(j.error||'Session expired')}
  if(!r.ok)throw new Error(j.error||'Request failed ('+r.status+')');return j}
function studentOut(expired){localStorage.removeItem(STK);clearInterval(POLL);ME=null;document.body.classList.remove('student');$('#stu').innerHTML='';loginGate(expired?'Your session expired — please sign in again.':'')}
async function startStudent(){
  const o=await sapi('me');ME={role:'student',roll_no:o.student.roll_no,full_name:o.student.name,email:''};gate('');document.body.classList.add('student');
  $$('.uname').forEach(e=>e.textContent=o.student.name);$$('.urole').forEach(e=>e.textContent='● '+o.student.roll_no);$$('.uav').forEach(e=>e.textContent=o.student.name[0]);
  buildStudent();paintStudent(o);clearInterval(POLL);POLL=setInterval(()=>{if(!document.hidden&&ME&&ME.role==='student')pollStudent()},(window.CX||{}).pollMs||8000)}
async function pollStudent(){try{paintStudent(await sapi('me'))}catch(e){}}
document.addEventListener('submit',async e=>{
  if(e.target.id!=='slf')return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;$('#slerr').textContent='';
  try{const r=await sapi('login',{roll:f.roll.value,code:f.code.value},{noToken:true});localStorage.setItem(STK,r.token);await startStudent()}
  catch(err){$('#slerr').textContent=err.message}finally{b.disabled=false}});
async function boot2(){
  const C=window.CX||{};
  if(!C.url||C.url.includes('YOUR-PROJECT')||!C.anon||C.anon.includes('YOUR-ANON')){gate('<p>This site is not configured yet.</p><p>Open <b>config.js</b> on your host and paste your Supabase <b>project URL</b> and <b>anon key</b> (Project Settings → API), redeploy, then hard-refresh. <a href="check.html">Run the setup check</a></p>');return}
  if(!/^https:\/\/.+\.supabase\.(co|in)\/?$/.test(C.url)&&!/^http:\/\/localhost/.test(C.url))throw new Error('config.js url looks wrong: '+C.url);
  TR.push('config: '+C.url);FNB=C.fnBase||C.url.replace(/\/$/,'')+'/functions/v1';
  const qs=new URLSearchParams(location.search),gp=qs.get('google'),gm=qs.get('msg'),oe=qs.get('error_description')||new URLSearchParams(location.hash.slice(1)).get('error_description');
  if(oe){history.replaceState(null,'',location.pathname);throw new Error(oe.replace(/\+/g,' '))}
  if(localStorage.getItem(STK)){try{await startStudent()}catch(e){if(localStorage.getItem(STK))fail('Could not load your portal',e)}return}
  if(typeof supabase==='undefined'||!supabase.createClient){loginGate('Faculty sign-in is unavailable: the Supabase library did not load (blocked network or CDN).');return}
  sb=supabase.createClient(C.url,C.anon);
  const gs=await sb.auth.getSession();if(gs.error)throw gs.error;const session=gs.data.session;TR.push(session?'session: '+(session.user.email||session.user.id):'session: none');
  if(!session){loginGate();return}
  const er=await sb.rpc('ensure_profile');let p=er.data;
  if(!p){const q=await sb.from('profiles').select('*').eq('id',session.user.id).maybeSingle();if(q.error)throw q.error;p=q.data;if(!p&&er.error)throw er.error}
  TR.push(p?'profile: '+p.role:'profile: none');
  if(!p){gate('<p>Your profile could not be created. Run supabase/schema.sql, then sign in again.</p><button class="big" data-act="signout">Sign out</button>');return}
  if(p.role!=='faculty'){gate(`<p>This Google account (${esc(p.email)}) is not registered as faculty.</p><p>Students sign in with their roll number and access code.</p><button class="big" data-act="signout">Use another account</button>`);return}
  ME=p;gate('');document.body.classList.add('faculty');
  const nm=p.full_name||p.email;$$('.uname').forEach(e=>e.textContent=nm);$$('.urole').forEach(e=>e.textContent='● Faculty');$$('.uav').forEach(e=>e.textContent=nm[0].toUpperCase());
  await loadFaculty();
  if(gp){history.replaceState(null,'',location.pathname);toast(gp==='connected'?'Google connected ✓ — your Drive folder and Sheet are ready':'Google connection failed: '+(gm||'unknown error'))}
  const r=()=>{clearTimeout(RT);RT=setTimeout(()=>loadFaculty(),400)};
  let ch=sb.channel('cx');['students','certificates','notifications','sync_reports','audit_logs','requirements'].forEach(t=>{ch=ch.on('postgres_changes',{event:'*',schema:'public',table:t},r)});ch.subscribe(s=>{if(s==='SUBSCRIBED')r()});
}
async function loadFaculty(){
  try{
    const [stu,certs,cfg,last,cron,act,reqs,gs,acc]=await Promise.all([
      fetchAll((a,b)=>sb.from('student_status').select('*').order('roll_no').range(a,b)),
      fetchAll((a,b)=>sb.from('certificates').select('id,roll_no,category,title,authority,cert_date,year,section,file_name,drive_link,in_drive,in_sheet,created_at,requirement_id,late').order('created_at').range(a,b)),
      ok(sb.from('settings').select('*').eq('id',1).single()),
      ok(sb.from('sync_reports').select('created_at').order('created_at',{ascending:false}).limit(1)),
      ok(sb.from('sync_reports').select('created_at').eq('triggered_by','cron').order('created_at',{ascending:false}).limit(1)),
      ok(sb.from('audit_logs').select('action,actor,details,created_at').order('created_at',{ascending:false}).limit(8)),
      ok(sb.from('requirements').select('*').order('sort')),
      ok(sb.from('google_status').select('*').limit(1)),
      fetchAll((a,b)=>sb.from('student_access').select('roll_no,last_login,locked').range(a,b))]);
    ST=stu.map(x=>({r:x.roll_no,n:x.name,sec:x.section,d:x.drive_files,s:x.sheet_rows,sub:x.submitted,c:x.categories||[],ap:x.approval,fb:x.feedback_reason,rq:x.req_total||0,rd:x.req_done||0}));
    CERTS=certs;DUPS=dupExtras(certs).length;SET=cfg;LAST=last[0];ACT=act;REQS=reqs;GS=gs[0]||null;ACC=new Map(acc.map(x=>[x.roll_no,x]));AUTO=!!(cron[0]&&Date.now()-new Date(cron[0].created_at)<20*60000);
    $$('.cnt').forEach(e=>e.textContent=ST.length);
    const nr=DUPS+ST.filter(F.MIS[1]).length,nb=$('#nrv');nb.textContent=nr;nb.classList.toggle('hidden',!nr);
    $('#lnkDrive').href=`https://drive.google.com/drive/folders/${SET.drive_folder_id||''}`;$('#lnkSheet').href=`https://docs.google.com/spreadsheets/d/${SET.spreadsheet_id||''}`;
    const t=LAST?new Date(LAST.created_at):null;$('#synced').textContent=t?p2(t.getHours())+':'+p2(t.getMinutes()):'never';
    const al=$('#autolbl');al.textContent=AUTO?'Auto-sync on':'Auto-sync off';al.style.color=AUTO?'var(--gr)':'var(--am)';
    renderView();
  }catch(e){toast('Load failed: '+(e.message||e))}
}
/* ---------- faculty views ---------- */
const VIEWS=['dash','students','requirements','access','review','alerts','export','audit'];
function setView(v){VIEW=v;VIEWS.forEach(x=>$('#v-'+x).classList.toggle('hidden',x!==v));$$('[data-view]').forEach(b=>b.classList.toggle('on',b.dataset.view===v));$('#pgtitle').textContent=VT[v][0];$('#pgsub').textContent=VT[v][1];renderView(true);$('#top').scrollTop=0}
function renderView(force){if(VIEW==='dash')renderDash();else if(VIEW==='students'){chips();body()}else if(VIEW==='requirements')viewRequirements();else if(VIEW==='access')viewAccess();else if(VIEW==='review')viewReview();else if(VIEW==='audit')viewAudit();else if(VIEW==='export')viewExport();else if(VIEW==='alerts'&&(force||!$('#v-alerts').innerHTML)){viewAlerts();loadRecent()}}
const toLocal=d=>{const x=new Date(d),p=n=>String(n).padStart(2,'0');return `${x.getFullYear()}-${p(x.getMonth()+1)}-${p(x.getDate())}T${p(x.getHours())}:${p(x.getMinutes())}`};
const reqFields=(r={})=>[{n:'name',l:'Certificate type (what students see)',v:r.name||''},{n:'folder_name',l:'Drive folder name (empty = same as the type)',v:r.folder_name||''},{n:'description',l:'Short description',v:r.description||''},{n:'deadline',l:'Deadline',t:'datetime-local',v:r.deadline?toLocal(r.deadline):''},{n:'required',l:'Required?',opts:[['yes','Yes — required'],['no','No — optional']],v:r.required===false?'no':'yes'},{n:'max_mb',l:'Max file size in MB (up to 12)',t:'number',v:r.max_mb||10},{n:'sections',l:'Sections (comma separated — empty means everyone)',v:(r.sections||[]).join(', ')}];
const reqPayload=o=>({name:o.name.trim(),folder_name:(o.folder_name||'').trim()||null,description:(o.description||'').trim(),deadline:o.deadline?new Date(o.deadline).toISOString():null,required:o.required!=='no',max_mb:Math.max(1,Math.min(12,+o.max_mb||10)),sections:(o.sections||'').trim()?o.sections.split(',').map(x=>x.trim()).filter(Boolean):null});
function viewRequirements(){
  const rows=[...REQS].sort((a,b)=>(a.sort-b.sort)||String(a.created_at).localeCompare(String(b.created_at))),fmt=d=>d?new Date(d).toLocaleString(undefined,{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'No deadline';
  const prog=r=>{const sub=new Set(CERTS.filter(c=>c.requirement_id===r.id).map(c=>c.roll_no)).size,tgt=ST.filter(s=>!r.sections||!r.sections.length||r.sections.includes(s.sec)).length;return [sub,tgt]};
  $('#v-requirements').innerHTML=`<section class="card"><div class="row sb wrap"><div><h3>Certificate types</h3><p>Each type is a choice in the students’ “Certificate Type” list and has its own Drive folder. Mark a type required or give it a deadline to make it appear in students’ checklist.</p></div><div class="row"><button class="ghost" data-act="sendrem">${ic('bell')} Send reminders now</button><button class="btn b" data-act="addreq">${ic('plus')} Add certificate type</button></div></div></section>
  ${rows.length?`<div class="grid2">${rows.map(r=>{const [s,t]=prog(r),over=r.deadline&&new Date(r.deadline)<new Date();return `<section class="card ${r.active?'':'dim'}" data-req="${esc(r.name)}"><div class="row sb"><h3>${esc(r.name)} ${r.required?'':'<span class="tag">optional</span>'} ${r.active?'':'<span class="tag">archived</span>'}</h3><div class="row" style="gap:6px"><button class="ghost sm" data-act="editreq" data-id="${r.id}">Edit</button><button class="ghost sm" data-act="togreq" data-id="${r.id}">${r.active?'Archive':'Restore'}</button></div></div><p>${esc(r.description||'')}</p><p class="mono" style="margin-top:8px;${over&&r.active?'color:var(--rd)':''}">${fmt(r.deadline)}${over?' · overdue':''}</p><p style="margin-top:2px">${'Drive folder “'+esc(r.folder_name||r.name)+'” · '}${r.sections&&r.sections.length?'Sections: '+esc(r.sections.join(', ')):'All sections'} · max ${r.max_mb} MB</p><div class="pb" style="margin-top:12px"><i style="width:${pc(s,t)}%;background:var(--ac2)"></i></div><p style="margin-top:6px">${s} of ${t} students submitted</p></section>`}).join('')}</div>`:`<section class="card"><div class="empty">${ic('list')}<b>No certificate types yet</b><small>Add the types students can upload — for example Hackathons, Courses, Internships.</small></div></section>`}`}
async function viewAccess(){
  const el=$('#v-access');if(!el.innerHTML)el.innerHTML='<div class="skel" style="height:160px"></div>';
  try{ACC=new Map((await fetchAll((a,b)=>sb.from('student_access').select('*').range(a,b))).map(x=>[x.roll_no,x]))}catch(e){el.innerHTML=`<section class="card"><p>${esc(e.message)}</p></section>`;return}
  const state=s=>{const a=ACC.get(s.r);return !a?'NONE':a.locked?'LOCKED':a.last_login?'ACTIVE':'NEVER'},cnt={NONE:0,NEVER:0,ACTIVE:0,LOCKED:0};ST.forEach(s=>cnt[state(s)]++);
  const rows=ST.filter(s=>AF==='ALL'||state(s)===AF),lab={NONE:['No code','s-x'],NEVER:['Never signed in','s-d'],ACTIVE:['Active','s-v'],LOCKED:['Locked','s-m']};
  el.innerHTML=`<section class="card"><div class="row sb wrap"><div><h3>Student sign-in codes</h3><p>Students sign in with their roll number and a private code. Codes are shown once when generated — download or print them straight away.</p></div><div class="row">${LASTCODES.length?`<button class="ghost" data-act="showcodes">Last generated (${LASTCODES.length})</button>`:''}<button class="btn b" data-act="gencodes" ${cnt.NONE?'':'disabled'}>${ic('plus')} Generate codes for ${cnt.NONE} student${cnt.NONE===1?'':'s'}</button></div></div>
  <div class="chips" style="margin-top:16px">${[['ALL','All',ST.length],['NONE','No code',cnt.NONE],['NEVER','Never signed in',cnt.NEVER],['ACTIVE','Active',cnt.ACTIVE],['LOCKED','Locked',cnt.LOCKED]].map(([k,l,n])=>`<button class="ch ${AF===k?'on':''}" data-act="accf" data-v="${k}">${l}<em>${n}</em></button>`).join('')}</div></section>
  <section class="card"><div class="tw"><table class="tbl"><tr><th>Roll no</th><th>Name</th><th>Status</th><th>Last sign-in</th><th></th></tr>${rows.slice(0,300).map(s=>{const a=ACC.get(s.r),[l,c]=lab[state(s)];return `<tr><td class="mono">${s.r}</td><td>${esc(s.n)}</td><td><span class="stat ${c}">${l}</span></td><td>${a&&a.last_login?ago(a.last_login):'—'}</td><td><button class="ghost sm" data-act="resetcode" data-id="${s.r}">${a?'Reset code':'Create code'}</button></td></tr>`}).join('')}</table></div>${rows.length>300?`<p style="margin-top:8px">Showing 300 of ${rows.length}. Use the filters above.</p>`:''}${rows.length?'':`<div class="empty">${ic('users')}<b>Nobody here</b></div>`}</section>`}
function showCodes(title,codes){modal(`<h3>${title}</h3><p>These codes are shown <b>once</b> and are not stored anywhere readable. Download or print them now, then hand them to students privately.</p>${codes.length<=3?codes.map(c=>`<div class="item"><div><b>${esc(c.name)}</b><p class="mono">${c.roll_no}</p></div><b class="mono code">${c.code}</b></div>`).join(''):`<p><span class="tag good">${codes.length} codes ready</span></p>`}<div class="row"><button class="btn b" data-act="dlcodes">${ic('dl')} Download CSV</button><button class="ghost" data-act="printslips">Print slips</button><button class="btn o" data-act="mclose">Done</button></div>`)}
function printSlips(){const site=location.origin+location.pathname.replace(/[^/]*$/,''),html=`<!doctype html><title>Access slips</title><style>body{font:14px system-ui;margin:16px}.g{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.s{border:1px dashed #666;border-radius:8px;padding:12px;break-inside:avoid}.c{font:700 22px ui-monospace,monospace;letter-spacing:2px;margin:8px 0}small{color:#555}</style><div class="g">${LASTCODES.map(c=>`<div class="s"><b>Certifyx</b> — certificate upload<br>${esc(c.name)} · ${esc(c.roll_no)}<div class="c">${esc(c.code)}</div><small>Sign in at ${esc(site)} with your roll number and this code. Keep it private.</small></div>`).join('')}</div>`,w=window.open('','_blank');
  if(!w){toast('Pop-ups are blocked — allow them to print the slips, or use Download CSV');return}w.document.write(html);w.document.close();setTimeout(()=>{try{w.print()}catch(e){}},300)}
function viewExport(){const card=(ico,col,t,d,act,btn)=>`<section class="card xcard"><span class="kico" style="--c:${col}">${ic(ico)}</span><h3>${t}</h3><p>${d}</p><button class="ghost" data-act="${act}">${ic('dl')} ${btn}</button></section>`;
  $('#v-export').innerHTML=`<div class="grid2">${card('users','#3b82f6','Class summary (CSV)','One row per student: Drive files, Sheet responses, submitted flag and approval status.','export','Download CSV')}${card('cap','#f59e0b','Achievements sheet (CSV)','Your format: SLNO., Roll no., Name, Year, Section, Certificate, Title, Auth, Month with date — one row per certificate.','exportsheet','Download CSV')}${card('file','#06b6d4','All certificates (CSV)','Every certificate record with category, title, file name, Drive link and sync flags.','exportcerts','Download CSV')}${card('list','#a78bfa','Audit log (CSV)','Every upload, sync, approval and removal, with who did it and when.','exportaudit','Download CSV')}${card('cap','#22c55e','NAAC / accreditation report','Formatted list of verified students and their certificate categories, ready to archive or paste into a document.','naac','Download &amp; copy')}</div>`}
