  const fl=[rs.some(r=>r.status==='SUBMITTED')&&req.every(r=>r.status==='SUBMITTED'),cs.length>0&&cs.every(c=>c.in_drive),cs.length>0&&cs.every(c=>c.in_sheet),o.approval==='APPROVED'],cur=fl.indexOf(false),cl=o.approval==='APPROVED'?'s-v':o.approval==='REJECTED'?'s-x':'s-d';
  $('#sHead').innerHTML=`<section class="card"><div class="row sb"><div><h2 style="font-size:22px;letter-spacing:-.4px">Welcome, ${esc(o.student.name)}</h2><p class="mono" style="margin-top:2px">${o.student.roll_no} · ${esc(o.student.section||'')}</p></div><span class="stat ${cl}" id="sAppr">${o.approval.replace('_',' ')}</span></div><div class="steps">${['Submitted','Saved to Drive','Recorded in Sheet','Approved by faculty'].map((l,i)=>`<div class="step ${fl[i]?'done':i===cur?'cur':''}">${l}</div>`).join('')}</div>${o.feedback?`<p style="color:var(--rd);margin-top:16px">Faculty feedback: ${esc(o.feedback)}</p>`:''}</section>`;
  const dd=d=>new Date(d).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});
  $('#sReq').innerHTML=`<section class="card"><div class="ch2"><h3>Required for you <span class="tag">${done}/${rs.length} done</span></h3></div>${rs.length?rs.map(r=>`<div class="rq"><div class="f1"><b>${esc(r.name)}</b> ${r.required?'':'<span class="tag">optional</span>'}<small>${esc(r.description||'')}${r.deadline?` · due ${dd(r.deadline)}`:''}</small></div><span class="stat ${r.status==='SUBMITTED'?'s-v':r.status==='OVERDUE'?'s-x':'s-d'}">${r.status==='SUBMITTED'?(r.late?'SUBMITTED · LATE':'SUBMITTED ✓'):r.status}</span><button class="ghost sm" data-act="pickreq" data-id="${r.id}">${r.status==='SUBMITTED'?'Replace':'Upload'}</button></div>`).join(''):`<div class="empty">${ic('list')}<b>Nothing is required right now</b><small>You can still upload any certificate below.</small></div>`}</section>`;
  const sel=$('#upf [name=requirement_id]'),sig=all.map(r=>r.id+r.status+r.name).join();
  if(sel.dataset.sig!==sig){const cur0=sel.value;sel.innerHTML=all.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');sel.value=all.some(r=>r.id===cur0)?cur0:((all.find(r=>r.tracked&&r.status!=='SUBMITTED')||all[0]||{}).id||'');sel.dataset.sig=sig}
